            if (s.charAt(i) == s.charAt(j)) j++;
            pi[i] = j;
        }
    }

    static void buildAutomaton() {
        aut = new int[m + 1][2];
        for (int state = 0; state <= m; state++) {
            for (int c = 0; c < 2; c++) {
                if (state == m) {
                    int j = pi[m - 1];
                    while (j > 0 && (char) (c + '0') != s.charAt(j)) j = pi[j - 1];
                    if ((char) (c + '0') == s.charAt(j)) j++;
                    aut[state][c] = j;
                } else {
                    int j = state;
                    while (j > 0 && (char) (c + '0') != s.charAt(j)) j = pi[j - 1];
                    if (j < m && (char) (c + '0') == s.charAt(j)) j++;
                    aut[state][c] = j;
                }
            }
        }
    }

    static long countLinearNoMatch() {
        long[][] dp = new long[n + 1][m];
        dp[0][0] = 1;
        for (int i = 0; i < n; i++) {
            for (int st = 0; st < m; st++) {
                long val = dp[i][st];
                if (val == 0) continue;
                for (int c = 0; c < 2; c++) {
                    int ns = aut[st][c];
                    if (ns == m) continue;
                    dp[i + 1][ns] += val;
                }
            }
        }
        long res = 0;
        for (int st = 0; st < m; st++) res += dp[n][st];
        return res;
    }

    static long countLinearWithMatch() {
        long[][] dp = new long[n + 1][m + 1];
        dp[0][0] = 1;
        for (int i = 0; i < n; i++) {
            for (int st = 0; st <= m; st++) {
                long val = dp[i][st];
                if (val == 0) continue;
                for (int c = 0; c < 2; c++) {
                    int ns = aut[st][c];
                    if (ns == m) dp[i + 1][m] += val;
                    else dp[i + 1][ns] += val;
                }
            }
        }
        return dp[n][m];
    }

    static long countCyclicNoMatch() {
        long totalNoMatch = countLinearNoMatch();
        long withMatch = countLinearWithMatch();
        return totalNoMatch - withMatch;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        s = br.readLine().trim();
        m = s.length();
        buildPrefix();
        buildAutomaton();
