                if (s.charAt(j) == ch) j++;
                go[state][c] = j;
            }
        }
    }

    static long dfs(int pos, int state) {
        if (state == m) return 0;
        if (pos == n) return 1;
        if (vis[pos][state]) return dp[pos][state];
        vis[pos][state] = true;
        long res = 0;
        res += dfs(pos + 1, go[state][0]);
        res += dfs(pos + 1, go[state][1]);
        dp[pos][state] = res;
        return res;
    }

    static void buildComb() {
        C = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        s = br.readLine().trim();
        m = s.length();

        buildPi();
        buildAutomaton();

        dp = new long[n + 1][m];
        vis = new boolean[n + 1][m];
        long totalLinear = 1L << n;
        long noSub = dfs(0, 0);
        long withSub = totalLinear - noSub;

        buildComb();

        long[] f = new long[n + 1];
        for (int k = 1; k <= n; k++) {
            long sum = 0;
            for (int i = k; i <= n; i++) {
                long sign = ((i - k) % 2 == 0) ? 1 : -1;
                sum += sign * C[i][k] * (1L << (n - i));
            }
            f[k] = sum;
        }

        long ans = 0;
        for (int k = 1; k <= n; k++) {
            long gk = f[k];
            if (gk == 0) continue;
            long contrib = gk * (1L << (k - 1));
            ans += contrib;
        }

        System.out.println(ans);
    }
}

