public class Main {
    static int n, m;
    static String s;
    static int[] pi;
    static int[][] go;
    static long[][][] dp;
    static int FULL;

    static void buildAutomaton() {
        m = s.length();
        pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && s.charAt(i) != s.charAt(j)) j = pi[j - 1];
            if (s.charAt(i) == s.charAt(j)) j++;
            pi[i] = j;
        }
        go = new int[m + 1][2];
        for (int state = 0; state <= m; state++) {
            for (int c = 0; c < 2; c++) {
                if (state == m) {
                    int j = pi[m - 1];
                    while (j > 0 && (s.charAt(j) - '0') != c) j = pi[j - 1];
                    if ((s.charAt(j) - '0') == c) j++;
                    go[state][c] = j;
                } else {
                    int j = state;
                    while (j > 0 && (s.charAt(j) - '0') != c) j = pi[j - 1];
                    if (j < m && (s.charAt(j) - '0') == c) j++;
                    go[state][c] = j;
                }
            }
        }
    }

    static long solve(boolean forbid) {
        dp = new long[n + 1][m + 1][1 << m];
        dp[0][0][0] = 1;
        for (int len = 0; len < n; len++) {
            for (int state = 0; state <= m; state++) {
                for (int mask = 0; mask < (1 << m); mask++) {
                    long cur = dp[len][state][mask];
                    if (cur == 0) continue;
                    for (int c = 0; c < 2; c++) {
                        int ns = go[state][c];
                        int nmask = mask;
                        if (ns == m) {
                            int pos = len - m + 1;
                            if (pos >= 0 && pos < m) nmask |= (1 << pos);
                        }
                        if (forbid && ns == m) continue;
                        dp[len + 1][ns][nmask] += cur;
                    }
                }
            }
        }
        long res = 0;
        for (int state = 0; state <= m; state++) {
            for (int mask = 0; mask < (1 << m); mask++) {
                if (!forbid && (mask & FULL) == FULL) res += dp[n][state][mask];
                if (forbid) res += dp[n][state][mask];
            }
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        s = br.readLine().trim();
        m = s.length();
        buildAutomaton();
        FULL = (1 << m) - 1;
        long total = 1L << n;
        long bad = solve(true);
        long good = total - bad;
        System.out.println(good);
    }
}

